// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testRegression_property() public {
        address owner = address(this);

        c.XBornID();

        uint256 balance = c.balanceOf(owner);

        assertTrue(balance == 200000000e18, "balance should be totalDistributed");
    }
}
